css:
[data-theme-section="header"] { border-color: #e5e7eb; }

[data-theme-section="hero"] { min-height: 60vh; }
[data-theme-section="hero"] h1 { font-size: 3.5rem; font-weight: 400; letter-spacing: -0.03em; line-height: 1.1; }
[data-theme-section="hero"] p { font-size: 1.125rem; font-weight: 300; max-width: 32rem; margin-left: auto; margin-right: auto; }
[data-theme-section="hero"] a { font-weight: 500; border: 1px solid #000; background: transparent !important; color: #000 !important; padding: 0.75rem 2rem; letter-spacing: 0.02em; font-size: 0.875rem; }
[data-theme-section="hero"] a:hover { background: #000 !important; color: #fff !important; }

.theme-home-categories a { border-radius: 0; }
.theme-home-categories .aspect-square { aspect-ratio: 4/5; }

[data-theme-section="product-card"] { border: none; box-shadow: none; }
[data-theme-section="product-card"] img { border-radius: 0; }
[data-theme-section="product-card"] h3 { font-weight: 400; font-size: 0.875rem; }
[data-theme-section="product-card"] .font-bold { font-weight: 500; font-size: 0.875rem; }

[data-theme-section="home-image-text"] h2 { font-weight: 300; font-size: 2.5rem; letter-spacing: -0.02em; }
[data-theme-section="home-image-text"] p { font-weight: 300; }

[data-theme-section="home-trust"] { border-color: #f3f4f6; }

[data-theme-section="home-testimonials"] { background: #fafafa; }
[data-theme-section="home-testimonials"] > div > div > div { background: #fff; border: 1px solid #f3f4f6; border-radius: 0; box-shadow: none; }

[data-theme-section="home-new-arrivals"] h2,
[data-theme-section="home-best-sellers"] h2,
[data-theme-section="home-featured"] h2,
.theme-home-categories h2 { font-weight: 400; letter-spacing: -0.01em; }

[data-theme-section="footer"] { border-top: 1px solid #e5e7eb; }
.theme-footer-newsletter { background: #f9fafb !important; border-radius: 0 !important; }
.theme-footer-newsletter h3 { color: #111827 !important; font-weight: 500; }
.theme-footer-newsletter p { color: #6b7280 !important; }
.theme-footer-copyright { border-color: #e5e7eb !important; color: #9ca3af !important; }
.theme-footer h4 { color: #111827 !important; font-weight: 500; }
.theme-footer a { color: #6b7280; }
.theme-footer a:hover { color: #111827 !important; }

.theme-header-logo { font-weight: 500; letter-spacing: -0.02em; text-transform: uppercase; font-size: 0.875rem; }
